from collections import deque

def components(mask, dirs):
    h,w=mask.shape; lab=np.zeros((h,w),int); k=0
    for r,c in np.argwhere(mask):
        if lab[r,c]: continue
        k+=1; lab[r,c]=k; q=deque([(r,c)])
        while q:
            x,y=q.popleft()
            for dx,dy in dirs:
                a,b=x+dx,y+dy
                if 0<=a<h and 0<=b<w and mask[a,b] and not lab[a,b]: lab[a,b]=k;q.append((a,b))
    return lab,k
D4=[(-1,0),(1,0),(0,-1),(0,1)]
D8=[(i,j) for i in [-1,0,1] for j in [-1,0,1] if (i,j)!=(0,0)]

