    seedid=lab[0,0]
    ones=(g==1)
    labs1,n1=components(ones,d)
    edgeids=set()
    for r,c in np.argwhere(ones):
        if r==0 or c==0 or r==h-1 or c==w-1: edgeids.add(labs1[r,c])
    sel1=np.isin(labs1,list(edgeids)) if only_boundary_objects else ones
    out=g.copy()
    for r,c in np.argwhere(g==8):
