        hit=(border and (r==0 or c==0 or r==h-1 or c==w-1))
        for dr,dc in (D8 if adj==8 else D4):
            a,b=r+dr,c+dc
            if 0<=a<h and 0<=b<w and sel1[a,b]: hit=True
        if hit: out[r,c]=7
    return out
